{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Playful, grounded coaching for steady habits and measurable progress.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="page-root">
  <svg class="bg-pattern" aria-hidden="true"><use href="assets/img/pattern.svg#tile"></use></svg>
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="index.html">Home</a>
        <a href="about.html">Why Start</a>
        <a href="services.html">Playbooks</a>
        <a href="programs.html">Journeys</a>
        <a href="pricing.html">Fees</a>
        <a href="testimonials.html">Voices</a>
        <a href="book.html">Book</a>
        <a href="contact.html" class="muted">Hello</a>
      </nav>
      <a class="cta" href="{{PRIMARY_CTA_URL}}" id="primaryCta">{{PRIMARY_CTA_LABEL}}</a>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero wrap">
      <div class="hero-grid">
        <div>
          <h1 class="large">A playful, practical path to steadier living</h1>
          <p class="lead">We translate intentions into short, repeatable moves that build a month of progress. No medical promises—just habits, outcomes, and tools that stick.</p>

          <div class="hero-actions">
            <a class="btn primary" id="heroPrimary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="about.html">How it works</a>
          </div>
        </div>
        <div class="hero-panel">
          <div class="panel-card">
            <h3>Quick experiment: Mood → Method</h3>
            <p class="muted">Pick how you feel; we’ll suggest a short plan and adjust the CTA.</p>

            <div class="mood-select" id="moodSelect">
              <button data-mood="stressed">Stressed</button>
              <button data-mood="stuck">Stuck</button>
              <button data-mood="energized">Energized</button>
              <button data-mood="curious">Curious</button>
            </div>

            <div class="mood-result" id="moodResult">
              <strong id="moodLabel">Choose a mood</strong>
              <p id="moodDesc">We'll show a short way forward and tune the main action for you.</p>
              <a class="btn slim" id="moodCta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK -->
    <section class="framework wrap">
      <h2>How we shape forward motion</h2>
      <p class="muted">Three simple lenses guide every plan: Focus, Habit, Review. We build a monthly arc that fits your life.</p>
      <div class="frames">
        <div class="frame">
          <h4>Micro Focus</h4>
          <p>Pick one meaningful target each week. Tiny wins compound.</p>
        </div>
        <div class="frame">
          <h4>Ritual Habit</h4>
          <p>Design a two-minute anchor that cues the new behavior.</p>
        </div>
        <div class="frame">
          <h4>Weekly Review</h4>
          <p>Map adjustments, celebrate wins, and re-route where needed.</p>
        </div>
      </div>
    </section>

    <!-- OFFERS -->
    <section class="offers wrap">
      <h2>Playbooks & Journeys</h2>
      <p class="muted">Choose a format that fits your rhythm: short sprints, guided cohorts, or self-paced playbooks.</p>

      <div class="offer-list">
        <article class="offer">
          <h3>14-Day Reset (Sprint)</h3>
          <p class="muted">A concentrated two-week experiment to unstick one habit.</p>
          <p class="price">$149</p>
          <a class="btn" href="programs.html">See plan</a>
        </article>

        <article class="offer">
          <h3>Cohort: Month of Momentum</h3>
          <p class="muted">A guided cohort that blends daily micro-tasks with weekly live check-ins.</p>
          <p class="price">Cohort pricing • limited seats</p>
          <a class="btn" href="programs.html">Join cohort</a>
        </article>

        <article class="offer">
          <h3>Playbook Library</h3>
          <p class="muted">Self-paced templates for sleep, focus, and reset habits.</p>
          <p class="price">From $39</p>
          <a class="btn" href="services.html">Browse playbooks</a>
        </article>
      </div>
    </section>

    <!-- PROGRESS METER -->
    <section class="progress wrap">
      <h2>Your 30-day path map</h2>
      <p class="muted">Pick what matters now; we’ll draw a practical path for the next 30 days.</p>
      <div class="progress-grid">
        <form id="goalForm" class="goal-form">
          <label><input type="checkbox" name="goals" value="sleep"> Better sleep rhythm</label>
          <label><input type="checkbox" name="goals" value="movement"> Short daily movement</label>
          <label><input type="checkbox" name="goals" value="mindfulness"> 5 min mindful check-ins</label>
          <label><input type="checkbox" name="goals" value="hydration"> Hydration habit</label>
          <label><input type="checkbox" name="goals" value="workspace"> Workspace refresh</label>
          <div class="goal-actions">
            <button type="button" id="drawPath" class="btn">Map my 30 days</button>
            <button type="reset" class="btn ghost">Clear</button>
          </div>
        </form>

        <div class="path-map">
          <div id="pathSummary" class="path-summary muted">No goals selected yet.</div>
          <div id="pathCanvas" class="path-canvas" aria-hidden="false"></div>
        </div>
      </div>
    </section>

    <!-- PRICING (compact) -->
    <section class="pricing wrap">
      <h2>Fees & access</h2>
      <p class="muted">Transparent options for individuals and small groups.</p>
      <div class="pricing-grid">
        <div>
          <h4>Solo Cohort Spot</h4>
          <p class="muted">Monthly cohort — group coaching, weekly check-ins.</p>
          <p class="price">$79 / month</p>
        </div>
        <div>
          <h4>Focused Sprint</h4>
          <p class="muted">Two-week intensive with daily prompts.</p>
          <p class="price">$149 one-time</p>
        </div>
        <div>
          <h4>Playbook Access</h4>
          <p class="muted">Library of self-paced templates and guides.</p>
          <p class="price">From $39</p>
        </div>
      </div>
    </section>

    <!-- TESTIMONIALS -->
    <section class="testimonials wrap">
      <h2>Voices</h2>
      <blockquote>
        "The month plan turned daily indecision into a tiny checklist that actually stuck."<cite>— S.</cite>
      </blockquote>
      <blockquote>
        "I joined a cohort and the small daily tasks changed how I start mornings."<cite>— R.</cite>
      </blockquote>
    </section>

    <!-- CTA -->
    <section class="final-cta wrap">
      <h2>Ready to try a short experiment?</h2>
      <p class="muted">Book a quick discovery and we’ll pick a starting micro-focus together.</p>
      <a class="btn large" id="finalPrimary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </section>

    <footer class="site-footer">
      <div class="wrap foot-grid">
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <p class="muted">Serving {{CITY}}, {{STATE}} — coaching for steady outcomes.</p>
        </div>
        <div>
          <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
          <a href="tel:{{PHONE}}">{{PHONE}}</a>
        </div>
      </div>
    </footer>
  </main>
</body>
</html>"} 
