{"path":"assets/css/styles.css","content":"/* Bold & playful wellness coach CSS - no external fonts */
:root{
  --bg:#fffdf8;--accent:#ff6b6b;--accent-2:#6b8cff;--muted:#616161;--card:#ffffff;--accent-3:#ffb86b;
}
*{box-sizing:border-box}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;line-height:1.4;background:var(--bg);color:#111;margin:0}
.wrap{max-width:980px;margin:0 auto;padding:28px}
.site-header{background:linear-gradient(90deg, rgba(255,107,107,0.06), rgba(107,140,255,0.04));border-bottom:1px solid rgba(0,0,0,0.04)}
.site-header .wrap{display:flex;align-items:center;gap:12px}
.brand{font-weight:800;color:#111;text-decoration:none;font-size:18px}
.nav{margin-left:20px;display:flex;gap:12px}
.nav a{color:var(--muted);text-decoration:none;padding:8px 6px;border-radius:6px}
.nav a:hover{background:rgba(0,0,0,0.03)}
.cta{margin-left:auto;padding:9px 12px;border-radius:8px;background:var(--accent);color:white;text-decoration:none}
.cta:hover{opacity:0.95}
.hero{display:block;padding:36px 0}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:24px;align-items:start}
.large{font-size:36px;margin:0 0 8px}
.lead{color:var(--muted);margin:0 0 16px}
.hero-actions{display:flex;gap:10px}
.btn{display:inline-block;padding:10px 14px;background:var(--accent-2);color:white;text-decoration:none;border-radius:8px}
.btn.ghost{background:transparent;color:var(--accent-2);border:1px solid rgba(107,140,255,0.15)}
.btn.primary{background:var(--accent)}
.btn.slim{padding:6px 10px}
.hero-panel .panel-card{background:var(--card);border-radius:12px;padding:16px;box-shadow:0 6px 18px rgba(0,0,0,0.06)}
.mood-select{display:flex;gap:8px;margin:10px 0}
.mood-select button{flex:1;padding:8px;border-radius:8px;border:none;background:linear-gradient(180deg,#fff,#f6f6f8);cursor:pointer}
.mood-result{margin-top:12px}
.framework,.offers,.progress,.pricing,.testimonials,.final-cta{padding:28px 0;border-top:1px dashed rgba(0,0,0,0.03)}
.frames{display:flex;gap:12px;margin-top:12px}
.frame{background:linear-gradient(180deg,#fff,#fbfbff);padding:14px;border-radius:10px;flex:1}
.offer-list{display:flex;gap:12px;margin-top:12px}
.offer{background:linear-gradient(90deg,#fff,#fffefb);padding:14px;border-radius:10px;flex:1}
.price{font-weight:700;color:var(--accent-2)}
.progress-grid{display:grid;grid-template-columns:320px 1fr;gap:18px;align-items:start}
.goal-form label{display:block;margin:10px 0;color:var(--muted)}
.goal-actions{display:flex;gap:8px;margin-top:8px}
.path-canvas{padding:12px;border-radius:10px;background:linear-gradient(180deg,#ffffff,#fcfcff);min-height:80px;border:1px solid rgba(0,0,0,0.04)}
.path-canvas .dot{width:12px;height:12px;border-radius:50%;display:inline-block;margin:4px}
.path-summary{margin-bottom:8px}
.pricing-grid{display:flex;gap:12px}
.pricing-grid > div{background:#fff;padding:12px;border-radius:8px}
.testimonials blockquote{background:#fff;padding:12px;border-radius:8px;margin:12px 0}
.final-cta{text-align:center}
.large{font-size:22px}
.site-footer{border-top:1px solid rgba(0,0,0,0.04);padding:20px 0;margin-top:20px}
.foot-grid{display:flex;justify-content:space-between}
.muted{color:var(--muted)}
.bg-pattern{position:fixed;right:0;bottom:0;width:400px;height:400px;opacity:0.12;pointer-events:none}
@media(max-width:880px){
  .hero-grid{grid-template-columns:1fr}
  .progress-grid{grid-template-columns:1fr}
  .nav{display:none}
}
"} 
{"path":"assets/js/main.js","content":"// Interactive Mood-to-Method + 30-day path map
document.addEventListener('DOMContentLoaded',function(){
  // Mood selector
  const moodSelect = document.getElementById('moodSelect');
  const moodLabel = document.getElementById('moodLabel');
  const moodDesc = document.getElementById('moodDesc');
  const moodCta = document.getElementById('moodCta');
  const heroPrimary = document.getElementById('heroPrimary');
  const primaryCta = document.getElementById('primaryCta');
  const finalPrimary = document.getElementById('finalPrimary');

  const MOODS = {
    stressed: {
      name: 'Soothing Reset',
      desc: 'Short rituals and micro-breaks to release tension across a week.',
      cta: 'Start a Soothing Reset',
      tag: 'stressed'
    },
    stuck: {
      name: 'Tiny Unstick',
      desc: 'One tiny, repeatable move to rebuild momentum — tested in days.',
      cta: 'Try Tiny Unstick',
      tag: 'stuck'
    },
    energized: {
      name: 'Amplify Flow',
      desc: 'Channel energy into short, focused bursts and a simple review ritual.',
      cta: 'Amplify Flow Now',
      tag: 'energized'
    },
    curious: {
      name: 'Micro-Adventure',
      desc: 'Experiment with playful micro-tasks and note what lands.',
      cta: 'Launch a Micro-Adventure',
      tag: 'curious'
    }
  };

  moodSelect.addEventListener('click',function(e){
    const btn = e.target.closest('button');
    if(!btn) return;
    const mood = btn.dataset.mood;
    if(!MOODS[mood]) return;
    const data = MOODS[mood];
    moodLabel.textContent = data.name;
    moodDesc.textContent = data.desc;
    // Update CTA text and add query tag
    const newLabel = data.cta;
    const url = ({{PRIMARY_CTA_URL}} || '') + '?mood=' + data.tag;
    // If placeholders are present (server will replace), keep them for now but update visible text
    moodCta.textContent = newLabel;
    heroPrimary.textContent = newLabel;
    primaryCta.textContent = newLabel;
    finalPrimary.textContent = newLabel;
    // attach mood tag as data attribute for client flows
    moodCta.dataset.tag = data.tag;
    heroPrimary.dataset.tag = data.tag;
    primaryCta.dataset.tag = data.tag;
    finalPrimary.dataset.tag = data.tag;
  });

  // Path map
  const goalForm = document.getElementById('goalForm');
  const drawPathBtn = document.getElementById('drawPath');
  const pathCanvas = document.getElementById('pathCanvas');
  const pathSummary = document.getElementById('pathSummary');

  function randomChoice(arr){return arr[Math.floor(Math.random()*arr.length)];}

  const GOAL_MAP = {
    sleep: {color:'#6b8cff', actions:['Wind-down minute','Lighting check','Pre-sleep note']},
    movement: {color:'#ff6b6b', actions:['3-min walk','Desk stretch','3 squats']},
    mindfulness: {color:'#ffb86b', actions:['2-min breath','Body scan','Check-in']},
    hydration: {color:'#6bffb0', actions:['Glass before meal','Sip timer','Flavor water']},
    workspace: {color:'#b86bff', actions:['Desk clear','Air/plant','Posture check']}
  };

  function renderPath(selected){
    pathCanvas.innerHTML = '';
    if(selected.length===0){
      pathSummary.textContent = 'No goals selected yet.';
      return;
    }
    const bullets = [];
    // for 30 days create dots, rotate actions
    for(let d=1;d<=30;d++){
      const dot = document.createElement('span');
      dot.className = 'dot';
      // choose a goal to emphasize that day
      const goal = selected[(d-1)%selected.length];
      const meta = GOAL_MAP[goal];
      dot.style.background = meta.color;
      dot.title = 'Day ' + d + ' — ' + randomChoice(meta.actions);
      pathCanvas.appendChild(dot);
      bullets.push({day:d,goal:goal,action:dot.title});
      if(d%10===0) pathCanvas.appendChild(document.createElement('br'));
    }
    pathSummary.textContent = 'Mapped ' + selected.length + ' goal(s) across 30 days. Hover a dot for the day action.';
    // also expose a simple map object on window for demo/export
    window._lastPath = {generatedAt:Date.now(), goals:selected, bullets:bullets};
  }

  drawPathBtn.addEventListener('click',function(){
    const form = new FormData(goalForm);
    const goals = [];
    for(const val of form.getAll('goals')) goals.push(val);
    renderPath(goals);
  });

  // quick demo default: preselect movement + mindfulness
  // do not auto-run on small screens
  if(window.innerWidth>520){
    // prefill a light map
    const inputs = goalForm.querySelectorAll('input[name="goals"]');
    inputs.forEach(i=>{ if(i.value==='movement' || i.value==='mindfulness') i.checked=true });
    drawPathBtn.click();
  }

});
"} 
